// And groups predicates with the AND operator between them.
func And(predicates ...predicate.LiveRoom) predicate.LiveRoom {
	return predicate.LiveRoom(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.LiveRoom) predicate.LiveRoom {
	return predicate.LiveRoom(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.LiveRoom) predicate.LiveRoom {
	return predicate.LiveRoom(sql.NotPredicates(p))
}
